//!src/gateway/openclaw-id/owner-notices.ts
async function sendOwnerNotices(e){const t=e.events.filter(e=>e.type===`notify_owners`);if(t.length===0)return;const n=await e.target();for(const r of t){if(!n){e.log.info(`openclaw-id: owner notice ${r.event} not mailed (not registered with Discovery)`);continue}try{await n.client.sendOwnerNotice(n.clawId,{kind:`notice`,event:r.event,ref:r.ref});e.log.info(`openclaw-id: mailed owner notice ${r.event}`)}catch(t){e.log.warn(`openclaw-id: could not mail owner notice ${r.event}: ${t instanceof Error?t.message:String(t)}`)}}}export{sendOwnerNotices};